messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Low Poly Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const CYCLE_DURATION = 10.0;
    const STAND_TIME = 2.0;
    const WALK_TIME = 3.0;
    const RUN_TIME = 3.0;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x202025);
    scene.fog = new THREE.Fog(0x202025, 10, 50);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 2, 8);
    camera.lookAt(0, 1, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    scene.add(dirLight);

    // --- Materials ---
    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, flatShading: true });
    const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366cc, flatShading: true });
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x333333, flatShading: true });
    const shoeMat = new THREE.MeshStandardMaterial({ color: 0x222222, flatShading: true });
    const treadMat = new THREE.MeshStandardMaterial({ color: 0x111111, flatShading: true });

    // --- Geometry Helpers ---
    function createLimb(w, h, d, mat) {
        const geo = new THREE.BoxGeometry(w, h, d);
        geo.translate(0, -h/2, 0); // Pivot at top
        const mesh = new THREE.Mesh(geo, mat);
        mesh.castShadow = true;
        return mesh;
    }

    // --- Character Construction ---
    const character = new THREE.Group();

    // Hips (Root)
    const hips = new THREE.Group();
    hips.position.y = 1.0; // Ground level offset
    character.add(hips);

    // Torso
    const torso = new THREE.Group();
    torso.position.y = 0.1;
    hips.add(torso);
    const torsoMesh = createLimb(0.5, 0.6, 0.3, shirtMat);
    torsoMesh.position.y = 0.3; // Center relative to group
    torso.add(torsoMesh);

    // Head
    const head = new THREE.Group();
    head.position.y = 0.65;
    torso.add(head);
    const headMesh = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.35, 0.3), skinMat);
    headMesh.castShadow = true;
    head.add(headMesh);

    // Neck
    const neck = new THREE.Group();
    neck.position.y = 0.6;
    torso.add(neck);
    const neckMesh = createLimb(0.1, 0.1, 0.1, skinMat);
    neck.add(neckMesh);

    // Arms
    const leftArm = new THREE.Group();
    leftArm.position.set(0.3, 0.5, 0);
    torso.add(leftArm);
    const leftUpperArm = createLimb(0.15, 0.3, 0.15, shirtMat);
    leftArm.add(leftUpperArm);

    const leftForearm = new THREE.Group();
    leftForearm.position.y = -0.3;
    leftArm.add(leftForearm);
    const leftLowerArm = createLimb(0.12, 0.3, 0.12, skinMat);
    leftForearm.add(leftLowerArm);

    const rightArm = new THREE.Group();
    rightArm.position.set(-0.3, 0.5, 0);
    torso.add(rightArm);
    const rightUpperArm = createLimb(0.15, 0.3, 0.15, shirtMat);
    rightArm.add(rightUpperArm);

    const rightForearm = new THREE.Group();
    rightForearm.position.y = -0.3;
    rightArm.add(rightForearm);
    const rightLowerArm = createLimb(0.12, 0.3, 0.12, skinMat);
    rightForearm.add(rightLowerArm);

    // Legs
    const leftLeg = new THREE.Group();
    leftLeg.position.set(0.15, 0, 0);
    hips.add(leftLeg);
    const leftThigh = createLimb(0.2, 0.45, 0.2, pantsMat);
    leftLeg.add(leftThigh);

    const leftShin = new THREE.Group();
    leftShin.position.y = -0.45;
    leftLeg.add(leftShin);
    const leftCalf = createLimb(0.18, 0.45, 0.18, pantsMat);
    leftShin.add(leftCalf);

    const leftFoot = new THREE.Group();
    leftFoot.position.y = -0.45;
    leftShin.add(leftFoot);
    const leftFootMesh = createLimb(0.2, 0.1, 0.35, shoeMat);
    leftFootMesh.position.z = 0.1; // Toe forward
    leftFoot.add(leftFootMesh);

    const rightLeg = new THREE.Group();
    rightLeg.position.set(-0.15, 0, 0);
    hips.add(rightLeg);
    const rightThigh = createLimb(0.2, 0.45, 0.2, pantsMat);
    rightLeg.add(rightThigh);

    const rightShin = new THREE.Group();
    rightShin.position.y = -0.45;
    rightLeg.add(rightShin);
    const rightCalf = createLimb(0.18, 0.45, 0.18, pantsMat);
    rightShin.add(rightCalf);

    const rightFoot = new THREE.Group();
    rightFoot.position.y = -0.45;
    rightShin.add(rightFoot);
    const rightFootMesh = createLimb(0.2, 0.1, 0.35, shoeMat);
    rightFootMesh.position.z = 0.1;
    rightFoot.add(rightFootMesh);

    scene.add(character);

    // --- Treadmill ---
    const treadmillGroup = new THREE.Group();
    const beltGeo = new THREE.BoxGeometry(2, 0.1, 1.5);
    const belt = new THREE.Mesh(beltGeo, treadMat);
    belt.receiveShadow = true;
    treadmillGroup.add(belt);

    // Side rails
    const railGeo = new THREE.BoxGeometry(2.2, 0.4, 0.1);
    const railL = new THREE.Mesh(railGeo, treadMat);
    railL.position.set(0, 0.2, 0.75);
    treadmillGroup.add(railL);
    const railR = new THREE.Mesh(railGeo, treadMat);
    railR.position.set(0, 0.2, -0.75);
    treadmillGroup.add(railR);

    // Base
    const baseGeo = new THREE.BoxGeometry(2.2, 0.4, 1.6);
    const base = new THREE.Mesh(baseGeo, treadMat);
    base.position.y = -0.2;
    base.receiveShadow = true;
    treadmillGroup.add(base);

    treadmillGroup.position.y = -0.05;
    scene.add(treadmillGroup);

    // --- Animation Logic ---
    const clock = new THREE.Clock();

    // Helper for smooth transitions
    function lerpAngle(start, end, t) {
        // Simple linear interpolation for angles (works fine for small ranges)
        return start + (end - start) * t;
    }

    function animate() {
        requestAnimationFrame(animate);

        const elapsed = clock.getElapsedTime();
        const timeInCycle = elapsed % CYCLE_DURATION;

        // Determine State
        let state = 'stand';
        let stateTime = 0; // Time spent in current state

        if (timeInCycle < STAND_TIME) {
            state = 'stand';
            stateTime = timeInCycle;
        } else if (timeInCycle < STAND_TIME + WALK_TIME) {
            state = 'walk';
            stateTime = timeInCycle - STAND_TIME;
        } else {
            state = 'run';
            stateTime = timeInCycle - STAND_TIME - WALK_TIME;
        }

        // --- Animation Parameters ---

        // Base positions (Stand)
        const standHipX = 0;
        const standTorsoRot = 0;
        const standHeadRot = 0;
        const standArmAngle = 0.1; // Slight bend/offset
        const standLegAngle = 0;
        const standKneeAngle = 0;

        // Walk Parameters
        const walkSpeed = 1.5; // Frequency
        const walkHipBob = 0.05;
        const walkTorsoRot = 0.05;
        const walkArmSwing = 0.5; // Radians
        const walkLegSwing = 0.5;
        const walkKneeBend = 0.4;

        // Run Parameters
        const runSpeed = 3.0;
        const runHipBob = 0.15;
        const runTorsoRot = 0.15;
        const runArmSwing = 1.0;
        const runLegSwing = 1.2;
        const runKneeBend = 0.8;

        // --- Apply Animations ---

        // 1. Determine current targets based on state
        let targetHipBob = 0;
        let targetTorsoRot = 0;
        let targetArmSwing = 0;
        let targetLegSwing = 0;
        let targetKneeBend = 0;
        let speed = 0;

        if (state === 'stand') {
            // Smoothly transition to 0
            // We don't strictly need to lerp to 0 if we just set them, 
            // but lerping makes the start/stop smoother.
            // However, for a "stand still" phase, we want to be exactly still at the end of the transition.
            // Let's use a quick transition time.
            const transTime = 0.2;
            const t = Math.min(1, stateTime / transTime);

            // If we just entered stand, lerp to 0. If we've been standing, stay at 0.
            // Since we calculate from scratch every frame, we need to know previous state or just force 0 if t>=1
            // To keep it simple and robust without state memory:
            // We will calculate the values based on the current cycle time directly.

            // Actually, let's just set the "active" values. The sine waves handle the continuous motion.
            // For stand, we want everything to be 0.
            targetHipBob = 0;
            targetTorsoRot = 0;
            targetArmSwing = 0;
            targetLegSwing = 0;
            targetKneeBend = 0;
            speed = 0;
        } 
        else if (state === 'walk') {
            targetHipBob = walkHipBob;
            targetTorsoRot = walkTorsoRot;
            targetArmSwing = walkArmSwing;
            targetLegSwing = walkLegSwing;
            targetKneeBend = walkKneeBend;
            speed = walkSpeed;
        } 
        else { // Run
            targetHipBob = runHipBob;
            targetTorsoRot = runTorsoRot;
            targetArmSwing = runArmSwing;
            targetLegSwing = runLegSwing;
            targetKneeBend = runKneeBend;
            speed = runSpeed;
        }

        // 2. Smooth Transitions between states
        // We create a "blend factor" that goes from 0 to 1 over 0.3 seconds at the start of each state
        const transitionTime = 0.3;
        let blend = 1;

        // Check if we are at the beginning of a state (within transitionTime)
        // We need to know when the state started.
        let stateStart = 0;
        if (state === 'stand') stateStart = 0;
        if (state === 'walk') stateStart = STAND_TIME;
        if (state === 'run') stateStart = STAND_TIME + WALK_TIME;

        if (stateTime < transitionTime) {
            blend = stateTime / transitionTime;
        }

        // 3. Calculate Sine Waves
        // We use the global elapsed time for the sine wave so it doesn't reset, 
        // but we modulate the amplitude based on the current state blend.

        // Hip Bob (Bounce)
        const hipY = targetHipBob * blend * Math.abs(Math.sin(elapsed * speed * Math.PI));

        // Torso Rotation (Forward lean / twist)
        // For running, we want a forward lean. For walking, slight twist.
        // Let's use a simple forward lean for run, and side twist for walk/run
        const torsoRotZ = -targetTorsoRot * blend * Math.sin(elapsed * speed * Math.PI); // Forward lean
        const torsoRotY = targetTorsoRot * 0.5 * blend * Math.sin(elapsed * speed * Math.PI * 2); // Slight twist

        // Limb Angles
        const phase = elapsed * speed * Math.PI;
        const sinPhase = Math.sin(phase);
        const cosPhase = Math.cos(phase);

        // Left Leg
        const lLegAngle = targetLegSwing * blend * sinPhase;
        const lKneeAngle = -targetKneeBend * blend * Math.max(0, sinPhase); // Only bend when swinging back (negative sin)

        // Right Leg (Opposite phase)
        const rLegAngle = targetLegSwing * blend * sinPhase + Math.PI; // + PI offset
        // Actually, simpler: Right leg is opposite of left leg.
        // If Left is sin(t), Right is sin(t + PI) = -sin(t)
        const rLegAngleVal = -targetLegSwing * blend * sinPhase;
        const rKneeAngleVal = -targetKneeBend * blend * Math.max(0, -sinPhase);

        // Arms (Opposite to legs)
        // Left Arm matches Left Leg? No, Left Arm matches Right Leg.
        const lArmAngle = targetArmSwing * blend * sinPhase + Math.PI; // Opposite to left leg
        const rArmAngle = targetArmSwing * blend * sinPhase; // Same as left leg

        // 4. Apply to Meshes

        // Hips
        hips.position.y = 1.0 + hipY;
        hips.position.x = 0; // Center

        // Torso
        torso.rotation.z = torsoRotZ;
        torso.rotation.y = torsoRotY;

        // Head
        head.rotation.x = 0; // Keep looking forward/down slightly?
        head.rotation.z = -torsoRotZ * 0.5; // Counter lean slightly

        // Legs
        leftLeg.rotation.x = lLegAngle;
        leftShin.rotation.x = lKneeAngle;

        rightLeg.rotation.x = rLegAngleVal;
        rightShin.rotation.x = rKneeAngleVal;

        // Arms
        leftArm.rotation.x = lArmAngle;
        leftForearm.rotation.x = -0.2; // Slight bend always

        rightArm.rotation.x = rArmAngle;
        rightForearm.rotation.x = -0.2;

        // Treadmill Belt Animation (Visual only)
        // Move the belt texture or mesh slightly to simulate movement
        // Since we don't have texture, let's just move the belt mesh slightly back and forth 
        // to simulate the belt dragging? No, that looks weird.
        // Let's add some particles or just leave it static. 
        // A static belt is fine, the motion of the character implies the treadmill.

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();
</script>
</body>
</html>
```
